-- 2026-09-24: keep the seeded core menu aligned with the standalone finance plugin.
UPDATE hou_permission_menu
SET name = '商城结算', pid = 0, paths = '/mall/finance', display_pos = 'left', update_time = UNIX_TIMESTAMP()
WHERE id = 60007 AND perms = 'mall:finance';
UPDATE hou_permission_menu
SET name = CASE id WHEN 60121 THEN '结算概览' WHEN 60123 THEN '商城收支' WHEN 2039 THEN '结算设置' END,
