-- 超级管理员不绑定任何 RBAC 角色：无角色的 is_admin 会话权限集是字面 ["*"]
-- （生产 ① 的实测形态，permission 服务对超管返回全权通配）。若绑了角色（如「管理员」），
-- 会话权限会退化成该角色的菜单权限列表——精确比对的鉴权（如插件发布的
-- ROLE_MALL_ADMIN 闸门）会把超管拒掉。管理员角色留给真实业务管理员。
-- INSERT IGNORE INTO `hou_permission_user_role` (`user_id`, `role_id`) VALUES (1, 1);
